        self.val = val
        self.next = next

class LinkedList:
    def __init__(self):
        self.head = None

    def insert(self, index, val):
        """在指定索引位置插入节点（索引从0开始）"""
        new_node = ListNode(val)
        if index == 0:
            new_node.next = self.head
            self.head = new_node
            return
        cur = self.head
        for _ in range(index - 1):
            if cur is None:
                raise IndexError("Index out of range")
            cur = cur.next
        new_node.next = cur.next
        cur.next = new_node

    def delete(self, index):
        """删除指定索引的节点"""
        if self.head is None:
            raise IndexError("Empty list")
        if index == 0:
            self.head = self.head.next
            return
        cur = self.head
        for _ in range(index - 1):
            if cur.next is None:
                raise IndexError("Index out of range")
            cur = cur.next
        if cur.next is None:
            raise IndexError("Index out of range")
        cur.next = cur.next.next

    def display(self):
        cur = self.head
        vals = []
        while cur:
            vals.append(cur.val)
            cur = cur.next
        print(vals)
